reset role;

-- M-Core: Data table design principles rollout (Align/Rows/Density/Sticky/Cells/Actions).
-- Write-only. Run once in Supabase SQL Editor. Rerun-safe.
-- No schema changes — this phase is CSS/HTML only (reusable utility classes + applied to
-- Invoices List, Admin Referral Program, Admin Announcement History). No new table/column/RLS.

update public.dev_roadmap_items set stage = 'completed', module = 'core',
  description = 'Reusable data-table CSS utilities added globally (.num right-align+tabular-nums, .tcell truncate+tooltip, .tbl-row-acts hover/focus-reveal actions with touch fallback, .tbl-sticky-h/.tbl-sticky-c for future use). Applied to Invoices List, Admin Referral Program and Admin Announcement History tables: numeric columns right-aligned, long text (customer/partner names, emails) truncated with hover tooltip instead of wrapping mid-word, missing values standardised to an em-dash, invoice row actions now reveal on hover/focus (always visible on touch). Row hairline + hover (no zebra) and em-dash-for-empty were already the existing global default and are unchanged. Density kept at the existing single intentional row height (no mode switcher built — out of the discussed scope). Sticky header/column utilities are defined but not yet applied anywhere (deferred: no table in this round was wide/tall enough to clearly need it, and effect on the app''s own fixed header could not be visually verified). Remaining ~90 other tables in the app are unchanged — explicitly out of scope for this round.'
  where title = 'Data table design: Align/Rows/Density/Sticky/Cells/Actions';
insert into public.dev_roadmap_items (title, description, module, stage)
  select 'Data table design: Align/Rows/Density/Sticky/Cells/Actions', 'Reusable data-table CSS utilities added globally (.num right-align+tabular-nums, .tcell truncate+tooltip, .tbl-row-acts hover/focus-reveal actions with touch fallback, .tbl-sticky-h/.tbl-sticky-c for future use). Applied to Invoices List, Admin Referral Program and Admin Announcement History tables: numeric columns right-aligned, long text (customer/partner names, emails) truncated with hover tooltip instead of wrapping mid-word, missing values standardised to an em-dash, invoice row actions now reveal on hover/focus (always visible on touch). Row hairline + hover (no zebra) and em-dash-for-empty were already the existing global default and are unchanged. Density kept at the existing single intentional row height (no mode switcher built — out of the discussed scope). Sticky header/column utilities are defined but not yet applied anywhere (deferred: no table in this round was wide/tall enough to clearly need it, and effect on the app''s own fixed header could not be visually verified). Remaining ~90 other tables in the app are unchanged — explicitly out of scope for this round.', 'core', 'completed'
  where not exists (select 1 from public.dev_roadmap_items where title = 'Data table design: Align/Rows/Density/Sticky/Cells/Actions');
